using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class StartMountainCutChecks {
 public static string Ui(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Compiled edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/StreetLoopGreybox.unity");RaceFlow.ValidationSaveRoot=Path.GetFullPath("Temp/MountainPolishUiSave");new GameObject("Temporary startup UI checks").AddComponent<MountainPolishUiChecks>();EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;return "Started normal title and injected controller/keyboard checks with isolated saves";}
 public static string Ai(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Compiled edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/MountainLoopReverse.unity");RaceFlow.ValidationSaveRoot=Path.GetFullPath("Temp/MountainCutSave");AudioListener.volume=0;new GameObject("Temporary Summit rival checks").AddComponent<MountainCutChecks>();EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;return "Started one production rival Summit traversal";}
}
